'use strict';

// cspell:ignore nbformat

// MODULES //

var tape = require( 'tape' );
var validate = require( './../lib/validate_notebook.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof validate, 'function', 'main export is a function' );
	t.end();
});

tape( 'the validator enforces nbformat 4.5 and unique cell IDs', function test( t ) {
	var notebook = {
		'cells': [
			{
				'cell_type': 'markdown',
				'id': 'cell-1',
				'metadata': {},
				'source': [ '# Beep\n' ]
			}
		],
		'metadata': {},
		'nbformat': 4,
		'nbformat_minor': 5
	};

	t.strictEqual( validate( notebook ), true, 'accepts a valid notebook' );
	delete notebook.cells[ 0 ].id;
	t.strictEqual( validate( notebook ), false, 'rejects a cell without an ID' );
	notebook.cells[ 0 ].id = 'cell-1';
	notebook.cells.push( JSON.parse( JSON.stringify( notebook.cells[ 0 ] ) ) );
	t.strictEqual( validate( notebook ), false, 'rejects duplicate cell IDs' );
	t.strictEqual( validate.errors[ 0 ].keyword, 'uniqueCellId', 'returns a uniqueness error' );
	t.end();
});

tape( 'the validator enforces upstream code metadata and output constraints', function test( t ) {
	var notebook = {
		'cells': [
			{
				'cell_type': 'code',
				'execution_count': null,
				'id': 'cell-1',
				'metadata': {
					'execution': {
						'iopub.status.busy': '2026-08-30T00:00:00Z'
					}
				},
				'outputs': [],
				'source': [ '1;' ]
			}
		],
		'metadata': {},
		'nbformat': 4,
		'nbformat_minor': 5
	};

	t.strictEqual( validate( notebook ), true, 'accepts valid execution metadata' );
	notebook.cells[ 0 ].metadata.execution[ 'iopub.status.busy' ] = 42;
	t.strictEqual( validate( notebook ), false, 'rejects non-string execution metadata' );
	notebook.cells[ 0 ].metadata.execution[ 'iopub.status.busy' ] = '2026-08-30T00:00:00Z';
	notebook.cells[ 0 ].outputs.push({
		'output_type': 'stream',
		'name': 'stdout'
	});
	t.strictEqual( validate( notebook ), false, 'rejects an output missing required text' );
	notebook.cells[ 0 ].outputs[ 0 ].text = [ 'ok\n' ];
	t.strictEqual( validate( notebook ), true, 'accepts a complete stream output' );
	notebook.cells[ 0 ].outputs[ 0 ].extra = true;
	t.strictEqual( validate( notebook ), false, 'rejects an extra standard output property' );
	t.end();
});
